const normalizeReelUrl = (url: string | undefined | null): string => {
  if (!url) {
    return "";
  }

  // Keep local temporary blob/file/content URIs
  if (url.startsWith("blob:") || url.startsWith("file:") || url.startsWith("content:")) {
    return url;
  }

  // Handle local uploads with relative path for web preview and absolute domain for android APK
  if (url.startsWith("/uploads/") || url.startsWith("uploads/")) {
    const cleanPath = url.startsWith("/") ? url : `/${url}`;
    return resolveApiUrl(cleanPath);
  }

  // A URL that is already our playback proxy is canonical. NEVER normalize it
  // again, otherwise `/api/v1/reels/media/reels/...` becomes duplicated.
  if (url.includes("/api/v1/reels/media/")) {
    return url;
  }

  // Route all R2 reel objects through the API playback proxy. This endpoint
  // supports HTTP Range requests so the exact same stored file plays in both
  // Creator Hub and the public Reels feed.
  const reelsIndex = url.indexOf("reels/");
  if (reelsIndex !== -1 && !url.includes("/uploads/")) {
    const objectKey = url.substring(reelsIndex).split("?")[0].replace(/^\/+/, "");
    return resolveApiUrl(`/api/v1/reels/media/${objectKey.split("/").map(encodeURIComponent).join("/")}`);
  }

  // Old S3/R2 URLs are also converted to the same playback proxy.
  if (url.includes("cloudflarestorage.com") || url.includes("amazonaws.com") || url.includes("pardaisparty-reels")) {
    const parts = url.split("pardaisparty-reels/");
    if (parts.length > 1 && parts[1]) {
      const objectKey = parts[1].split("?")[0].replace(/^\/+/, "");
      return resolveApiUrl(`/api/v1/reels/media/${objectKey.split("/").map(encodeURIComponent).join("/")}`);
    }
  }

  return url;
};

/**
 * TikTok-style recommendation algorithm (Client-side)
 * Calculates a dynamic interest score for each reel based on user signals,
 * watch behavior, metadata matching, and general engagement signals.
 */
export function recommendReels(
  reelsList: any[],
  interactions: Record<string, {
    watchTime: number;
    completions: number;
    rewatches: number;
    skippedQuickly: boolean;
    likes: number;
    commentsCount: number;
    shares: number;
    saves: number;
    isFollowed: boolean;
  }> = {}
) {
  return [...reelsList].sort((a, b) => {
    // 1. Calculate general engagement score (baseline for trending/popular content)
    const popularityA = (a.likes || 0) * 1 + (a.commentsCount || 0) * 2 + (a.shares || 0) * 3 + (a.saves || 0) * 2;
    const popularityB = (b.likes || 0) * 1 + (b.commentsCount || 0) * 2 + (b.shares || 0) * 3 + (b.saves || 0) * 2;
    
    let scoreA = popularityA * 0.01;
    let scoreB = popularityB * 0.01;

    // 2. Adjust score based on explicit interactions
    const interA = interactions[a.id];
    const interB = interactions[b.id];

    if (interA) {
      scoreA += (interA.watchTime || 0) * 2;
      scoreA += (interA.completions || 0) * 25;
      scoreA += (interA.rewatches || 0) * 40;
      if (interA.skippedQuickly) {
        scoreA -= 50;
      }
    }

    if (interB) {
      scoreB += (interB.watchTime || 0) * 2;
      scoreB += (interB.completions || 0) * 25;
      scoreB += (interB.rewatches || 0) * 40;
      if (interB.skippedQuickly) {
        scoreB -= 50;
      }
    }

    // 3. Regional and language relevance boost
    const isPakA = a.location?.toLowerCase().includes("pakistan") || a.caption?.toLowerCase().includes("urdu") || a.caption?.toLowerCase().includes("sahr");
    const isPakB = b.location?.toLowerCase().includes("pakistan") || b.caption?.toLowerCase().includes("urdu") || b.caption?.toLowerCase().includes("sahr");
    
    if (isPakA) scoreA += 15;
    if (isPakB) scoreB += 15;

    // 4. Follow boost
    if (a.isFollowed) scoreA += 30;
    if (b.isFollowed) scoreB += 30;

    return scoreB - scoreA;
  });
}

interface ReelVideoPlayerProps {
  videoUrl: string;
  muted: boolean;
  isActive: boolean;
  videoBg?: string;
  onToggleMute: () => void;
}

const ReelVideoPlayer: React.FC<ReelVideoPlayerProps> = ({
  videoUrl,
  muted,
  isActive,
  videoBg = "bg-[#12121a]",
  onToggleMute,
}) => {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [hasError, setHasError] = useState<boolean>(false);
  const [isPlaying, setIsPlaying] = useState<boolean>(true);

  const cleanUrl = normalizeReelUrl(videoUrl);
  const [activeUrl, setActiveUrl] = useState<string>(cleanUrl);
  const [retryCount, setRetryCount] = useState<number>(0);

  // Keep activeUrl and retryCount in sync when videoUrl / cleanUrl changes
  useEffect(() => {
    setActiveUrl(cleanUrl);
    setRetryCount(0);
    setHasError(false);
  }, [cleanUrl]);

  // Play / Pause effect based on isActive state
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    let isSubscribed = true;

    if (isActive) {
      setHasError(false);
      setIsLoading(true);
      console.log(`[PARDAIS-PARTY PLAYER] Playing URL: "${activeUrl}" (original: "${videoUrl}")`);
      
      const playPromise = video.play();
      if (playPromise !== undefined) {
        playPromise
          .then(() => {
            if (isSubscribed) {
              setIsPlaying(true);
              setIsLoading(false);
            }
          })
          .catch((err) => {
            if (isSubscribed) {
              console.warn("[PARDAIS-PARTY PLAYER] Playback blocked or interrupted:", err);
              setIsPlaying(false);
              setIsLoading(false);
            }
          });
      }
    } else {
      try {
        video.pause();
      } catch (e) {}
      setIsPlaying(false);
    }

    return () => {
      isSubscribed = false;
    };
  }, [isActive, activeUrl]);

  // Full-scale memory and decoder cleanup on unmount
  useEffect(() => {
    return () => {
      const video = videoRef.current;
      if (video) {
        try {
          console.log("[PARDAIS-PARTY PLAYER] Disposing video player resources cleanly...");
          video.pause();
          video.src = "";
          video.load();
        } catch (e) {
          console.error("[PARDAIS-PARTY PLAYER] Error disposing player:", e);
        }
      }
    };
  }, []);

  // Handle Play/Pause Tap on video
  const handleVideoTap = () => {
    const video = videoRef.current;
    if (!video) return;

    if (isPlaying) {
      video.pause();
      setIsPlaying(false);
    } else {
      video.play()
        .then(() => {
          setIsPlaying(true);
          setHasError(false);
        })
        .catch((err) => {
          console.error("[PARDAIS-PARTY PLAYER] Manual play failed:", err);
        });
    }
  };

  const handleRetry = (e: React.MouseEvent) => {
    e.stopPropagation();
    setHasError(false);
    setIsLoading(true);
    setRetryCount(0);
    const video = videoRef.current;
    if (video) {
      console.log(`[PARDAIS-PARTY PLAYER] Manually retrying playback for URL: "${activeUrl}"`);
      video.load();
      video.play()
        .then(() => {
          setIsPlaying(true);
          setIsLoading(false);
        })
        .catch((err) => {
          console.error("[PARDAIS-PARTY PLAYER] Manual retry play failed:", err);
          setHasError(true);
          setIsLoading(false);
        });
    }
  };

  return (
    <div className={`absolute inset-0 ${videoBg} flex items-center justify-center overflow-hidden`}>
      {/* Real Video Element */}
      {!hasError && activeUrl && (
        <video
          ref={videoRef}
          src={activeUrl}
          className="w-full h-full object-cover z-0"
          loop
          playsInline
          muted={muted}
          onWaiting={() => setIsLoading(true)}
          onPlaying={() => {
            setIsLoading(false);
            setHasError(false);
          }}
          onCanPlay={() => setIsLoading(false)}
          onLoadedData={() => setIsLoading(false)}
          onError={(e) => {
            const errCode = (e.currentTarget as HTMLVideoElement)?.error?.code || 0;
            const errMsg = (e.currentTarget as HTMLVideoElement)?.error?.message || "Source or format unavailable";
            console.warn(`[PARDAIS-PARTY PLAYER] Native HTML5 video error note (code: ${errCode}, msg: "${errMsg}") on "${activeUrl}"`);
            
            // Never replace a user's uploaded reel with a demo/system video.
            // Retry the exact saved media URL only.

            if (retryCount < 2) {
              const nextRetry = retryCount + 1;
              console.warn(`[PARDAIS-PARTY PLAYER] Playback failed. Attempting retry ${nextRetry}/2 for: "${activeUrl}"`);
              setRetryCount(nextRetry);
              setHasError(false);
              setIsLoading(true);
              
              setTimeout(() => {
                const video = videoRef.current;
                if (video) {
                  video.load();
                  video.play().catch((err) => {
                    console.warn("[PARDAIS-PARTY PLAYER] Retry play call was blocked or failed:", err);
                  });
                }
              }, 500);
            } else {
              console.error("[PARDAIS-PARTY PLAYER] Video failed to play after 2 retries. Showing error overlay.");
              setHasError(true);
              setIsLoading(false);
            }
          }}
          onClick={handleVideoTap}
        />
      )}

      {/* Radial overlay to make text/controls pop */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/40 via-transparent to-black/80 pointer-events-none z-10" />

      {/* Loading Spinner */}
      {isLoading && !hasError && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/45 backdrop-blur-xs z-20 pointer-events-none animate-fade-in">
          <div className="w-10 h-10 border-4 border-t-[#ff007f] border-r-transparent border-b-[#ff007f]/20 border-l-[#ff007f]/60 rounded-full animate-spin" />
          <p className="text-[9px] font-mono font-black text-pink-400 mt-2.5 uppercase tracking-widest animate-pulse">
            Buffering HD Stream...
          </p>
        </div>
      )}

      {/* Error / Retry overlay */}
      {hasError && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/90 p-6 text-center z-30">
          <span className="text-2xl mb-1 animate-bounce">⚠️</span>
          <p className="text-[10px] font-black text-red-400 uppercase tracking-wider">Playback Connection Failed</p>
          <p className="text-[8px] text-gray-400 mt-1 max-w-[220px] leading-normal font-medium">
            The R2 media link failed to load or is still provisioning.
          </p>
          <button
            type="button"
            onClick={handleRetry}
            className="mt-3 bg-gradient-to-r from-[#ff007f] to-[#7b2cbf] hover:from-pink-600 hover:to-purple-700 text-white font-mono font-black text-[8px] uppercase tracking-wider px-4 py-2 rounded-full border border-pink-400/30 shadow-lg transition-all active:scale-95 cursor-pointer"
          >
            🔄 Retry Loading
          </button>
        </div>
      )}

      {/* Large visual Pause Overlay Indicator */}
      {!isPlaying && !isLoading && !hasError && (
        <div 
          onClick={handleVideoTap}
          className="absolute inset-0 flex items-center justify-center bg-black/25 z-20 cursor-pointer animate-fade-in"
        >
          <div className="w-12 h-12 rounded-full bg-black/60 border border-white/10 flex items-center justify-center text-white text-md shadow-xl scale-110 hover:scale-115 transition-transform duration-200">
            ▶
          </div>
        </div>
      )}

      {/* Global Mute Toggle Trigger (floating, bottom-right) */}
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          onToggleMute();
        }}
        className="absolute bottom-24 right-3 w-8 h-8 rounded-full bg-black/50 border border-white/10 flex items-center justify-center text-white text-xs z-35 transition-all hover:bg-black/80 hover:scale-105 active:scale-95"
        title={muted ? "Unmute Sound" : "Mute Sound"}
      >
        {muted ? "🔇" : "🔊"}
      </button>
    </div>
  );
};

