  // Restore authenticated session from backend on app load
  useEffect(() => {
    syncNominatedAdminEmails();
    const restoreSession = async () => {
      // 1. Check if returning from Google Sign-In redirect
      try {
        if (clientAuth) {
          const redirectResult = await getRedirectResult(clientAuth);
          if (redirectResult?.user) {
            console.log("[GOOGLE AUTH] Redirect sign-in result detected on app load");
            await processGoogleAuthUser(redirectResult.user);
            return;
          }
        }
      } catch (redirectErr) {
        console.warn("[GOOGLE AUTH] Redirect result processing warning:", redirectErr);
      }

      // 2. Verify stored session token
      const token = localStorage.getItem("pardais_auth_token");
      const savedUserRaw = localStorage.getItem("pardais_user_profile");
      let savedProfile: UserProfile | null = null;
      if (savedUserRaw) {
        try { savedProfile = JSON.parse(savedUserRaw); } catch (e) {}
      }

      if (savedProfile && (savedProfile.username || savedProfile.uniqueId)) {
        setUser(savedProfile);
        setIsLoggedIn(true);
      }

      if (!token) {
        if (!savedProfile) {
          refreshSession().then(() => {
            setIsLoggedIn(true);
          });
        }
        return;
      }

      authenticatedFetch("/api/v1/auth/me")
        .then(res => {
          if (!res.ok) throw new Error("Session expired or invalid token.");
          return res.json();
        })
        .then(data => {
          if (data && data.user) {
            const sameAccount = Boolean(
              savedProfile &&
              ((savedProfile.uid && data.user.uid && savedProfile.uid === data.user.uid) ||
               (savedProfile.email && data.user.email && String(savedProfile.email).toLowerCase() === String(data.user.email).toLowerCase()))
            );
            const localProfile = sameAccount ? savedProfile : null;
            const preservedAvatar = data.user.avatar || localProfile?.avatar || "";
            const mergedUser: UserProfile = {
              ...data.user,
              // Backend is authoritative for account identity. Never reuse a previous
              // account's Pardais ID, username or name after a different account logs in.
              fullName: data.user.fullName || "",
              username: data.user.username || "",
              uniqueId: data.user.uniqueId || "",
              avatar: preservedAvatar,
              avatarUrl: data.user.avatarUrl || preservedAvatar,
              bio: localProfile?.bio || data.user.bio,
              gender: localProfile?.gender || data.user.gender,
              dob: localProfile?.dob || data.user.dob,
              phoneNumber: localProfile?.phoneNumber || data.user.phoneNumber,
              kycStatus: localProfile?.kycStatus || data.user.kycStatus,
              isVerified: data.user.isVerified !== undefined ? data.user.isVerified : localProfile?.isVerified,
            };
            setUser(mergedUser);
            setIsLoggedIn(true);
            localStorage.setItem("pardais_user_profile", JSON.stringify(mergedUser));
            lastSavedUserRef.current = JSON.stringify(mergedUser);
          }
        })
        .catch(err => {
          console.warn("[PARDAIS AUTH RESTORE] Session verification notice:", err.message);
        });
    };

    restoreSession();
  }, []);

  // Sync login status
