  // Camera State & Handlers for Avatar Profile Photo Capture
  const [showAvatarCameraModal, setShowAvatarCameraModal] = useState<boolean>(false);
  const [avatarCameraStream, setAvatarCameraStream] = useState<MediaStream | null>(null);
  const avatarVideoRef = useRef<HTMLVideoElement | null>(null);

  const startAvatarCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user", width: { ideal: 480 }, height: { ideal: 480 } } });
      setAvatarCameraStream(stream);
      setShowAvatarCameraModal(true);
      setTimeout(() => {
        if (avatarVideoRef.current) {
          avatarVideoRef.current.srcObject = stream;
          avatarVideoRef.current.play().catch(e => console.warn("Avatar camera stream play notice:", e));
        }
      }, 150);
    } catch (err) {
      console.warn("Direct camera access failed or denied, opening native file camera picker:", err);
      document.getElementById("avatar-camera-file-input")?.click();
    }
  };

  const stopAvatarCamera = () => {
    if (avatarCameraStream) {
      avatarCameraStream.getTracks().forEach(track => track.stop());
      setAvatarCameraStream(null);
    }
    setShowAvatarCameraModal(false);
  };

  const captureAvatarFromCamera = () => {
    if (avatarVideoRef.current) {
      const video = avatarVideoRef.current;
      const canvas = document.createElement("canvas");
      canvas.width = video.videoWidth || 400;
      canvas.height = video.videoHeight || 400;
      const ctx = canvas.getContext("2d");
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL("image/jpeg", 0.9);
        // Keep the camera capture as an actual File. Do not rely on fetch(data:...),
        // because authenticatedFetch intentionally rewrites fetch URLs to the API
        // and Android WebView can reject data: URLs as a network request.
        setEditAvatar(dataUrl);
        try {
          const comma = dataUrl.indexOf(",");
          const meta = comma >= 0 ? dataUrl.slice(0, comma) : "data:image/jpeg;base64";
          const base64 = comma >= 0 ? dataUrl.slice(comma + 1) : dataUrl;
          const binary = atob(base64);
          const bytes = new Uint8Array(binary.length);
          for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
          const mime = /data:([^;]+)/i.exec(meta)?.[1] || "image/jpeg";
          setEditAvatarFile(new File([bytes], `avatar-camera-${Date.now()}.jpg`, { type: mime }));
        } catch (fileErr) {
          console.warn("[PARDAIS PROFILE] Could not create camera File; keeping data URL preview:", fileErr);
          setEditAvatarFile(null);
        }
      }
    }
    stopAvatarCamera();
  };
  const [reelLocation, setReelLocation] = useState<string>("");
