  // Real-time Reels sync with Firestore database
  useEffect(() => {
    const q = query(collection(db, "reels"), orderBy("createdAt", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const firestoreReels = snapshot.docs.map(doc => {
        const data = doc.data();
        let rawUrl = data.videoUrl || data.publicUrl || data.mediaUrl || "";
        let finalUrl = "";
        
        if (rawUrl && (rawUrl.startsWith("/uploads/") || rawUrl.startsWith("uploads/") || rawUrl.startsWith("blob:") || rawUrl.startsWith("file:"))) {
          finalUrl = normalizeReelUrl(rawUrl);
        } else if (data.objectKey && !data.objectKey.startsWith("uploads/")) {
          // Never build a direct R2 URL here. Use the same playback proxy as
          // newly uploaded reels so Creator Hub and public Reels share one
          // canonical media URL.
          finalUrl = normalizeReelUrl(`https://media.pardaisparty.soulverseapps.com/${data.objectKey}`);
        } else {
          finalUrl = normalizeReelUrl(rawUrl);
        }

        return {
          id: doc.id,
          creator: data.creator || "Anonymous Creator",
          avatar: data.avatar || "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&h=150&q=80",
          caption: data.caption || "",
          song: data.song || "Original Sound",
          videoBg: data.videoBg || "bg-gradient-to-tr from-[#ff007f] via-[#12121a] to-[#7b2cbf]",
          videoUrl: finalUrl,
          likes: data.likes || 0,
          commentsCount: data.commentsCount || 0,
          liked: data.liked || false,
          privacy: data.privacy || "public",
          location: data.location || "Lahore, Pakistan",
          saves: data.saves || 0,
          saved: data.saved || false,
          shares: data.shares || 0,
          downloads: data.downloads || 0,
          isFollowed: data.isFollowed || false,
          comments: data.comments || [],
          uploaderId: data.uploaderId || "",
          createdAt: data.createdAt || ""
        };
      });
      
      if (firestoreReels.length > 0) {
        setReels(prev => {
          // Filter out private reels from the main public feed
          const publicFirestoreReels = (firestoreReels || []).filter(r => r && r.privacy !== "private");
          const staticReels = (prev || []).filter(r => r && r.id && typeof r.id === "string" && (r.id.startsWith("r") || !publicFirestoreReels.some(fr => fr && fr.id === r.id)));
          const raw = [...publicFirestoreReels, ...staticReels];
          const seen = new Set();
          return raw.filter(item => {
            if (!item || !item.id) return false;
            if (seen.has(item.id)) return false;
            seen.add(item.id);
            return true;
          });
        });

        // Sync profileReels dynamically from Firestore as well!
        const myReels = (firestoreReels || []).filter(r => r && (r.uploaderId === user.uniqueId || (r.uploaderId === "" && r.creator === (user.fullName || user.username))));
        
        const myUploaded = (myReels || []).filter(r => r && r.privacy !== "private").map(r => ({
          id: r.id,
          title: r.caption ? (r.caption.split(" ").slice(0, 4).join(" ") + "...") : "My Clip 🎬",
          views: r.views ?? 0,
          likes: r.likes,
          liked: r.liked,
          videoBg: r.videoBg,
          videoUrl: r.videoUrl,
          caption: r.caption,
          song: r.song,
          comments: (r.comments || []).map((c: any) => typeof c === 'string' ? c : (c.text || "")),
          duration: "0:30",
          location: r.location,
          isPrivate: false,
          privacy: "public",
          saves: r.saves,
          shares: r.shares,
          downloads: r.downloads,
          creator: r.creator,
          avatar: r.avatar
        }));

        const myPrivate = (myReels || []).filter(r => r && r.privacy === "private").map(r => ({
          id: r.id,
          title: r.caption ? (r.caption.split(" ").slice(0, 4).join(" ") + "...") : "My Private Clip 🔒",
          views: "Host Private",
          likes: r.likes,
          liked: r.liked,
          videoBg: r.videoBg,
          videoUrl: r.videoUrl,
          caption: r.caption,
          song: r.song,
          comments: (r.comments || []).map((c: any) => typeof c === 'string' ? c : (c.text || "")),
          duration: "0:30",
          location: r.location,
          isPrivate: true,
          privacy: "private",
          saves: r.saves,
          shares: r.shares,
          downloads: r.downloads,
          creator: r.creator,
          avatar: r.avatar
        }));

        setProfileReels(prev => {
          const dedupe = (list: any[]) => {
            const seen = new Set();
            return (list || []).filter(item => {
              if (!item || !item.id) return false;
              if (seen.has(item.id)) return false;
              seen.add(item.id);
              return true;
            });
          };
          const prevUploaded = prev?.uploaded || [];
          const prevPrivate = prev?.private || [];
          const nonDbUploaded = prevUploaded.filter(r => r && r.id && !myUploaded.some(mu => mu && mu.id === r.id));
          const nonDbPrivate = prevPrivate.filter(r => r && r.id && !myPrivate.some(mp => mp && mp.id === r.id));
          return {
            ...prev,
            uploaded: dedupe([...myUploaded, ...nonDbUploaded]),
            private: dedupe([...myPrivate, ...nonDbPrivate])
          };
        });
      }
    }, (error) => {
      console.error("Firestore reels subscription error:", error);
    });
    return () => unsubscribe();
  }, [user.uniqueId, user.fullName]);

  // Top header interactive states
