  const handleKycFileChange = (e: React.ChangeEvent<HTMLInputElement>, side: "front" | "back") => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === "string") {
          if (side === "front") {
            setKycFrontImage(reader.result);
          } else {
            setKycBackImage(reader.result);
          }
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const runKycScan = () => {
    setKycScanning(true);
    setKycProgress(0);
    setKycScanSuccess(false);
    setKycScanMessage("Requesting device camera security access...");
    
    // Start camera stream (simulated if blocked)
    startKycCamera();

    let currentProgress = 0;
    const interval = setInterval(() => {
      currentProgress += 2;
      if (currentProgress > 100) {
        currentProgress = 100;
      }
      setKycProgress(currentProgress);

      if (currentProgress < 20) {
        setKycScanMessage("Initializing biometric scanning grid...");
      } else if (currentProgress < 45) {
        setKycScanMessage("Mapping facial landmarks (3D Mesh)... Hold still.");
      } else if (currentProgress < 70) {
        setKycScanMessage("Proving liveness detection... Please blink your eyes.");
      } else if (currentProgress < 90) {
        setKycScanMessage("Matching registration registry records (Pakistan Sim database)...");
      } else if (currentProgress < 100) {
        setKycScanMessage("Securing encrypted verification block...");
      } else {
        clearInterval(interval);
        setKycScanning(false);
        setKycScanSuccess(true);
        setKycScanMessage("Biometric Match Completed successfully! ✨");
        stopKycCamera();
      }
    }, 80); // 100% in 4 seconds
  };

  const [reels, setReels] = useState<any[]>([]);

  // Dynamically sync profileReels from real user uploads, liked, saved items & stories!
  useEffect(() => {
    const userFullName = user.fullName || "";
    const userUsername = user.username || "";
    const userUniqueId = user.uniqueId || "";

    // 1. Collect uploaded reels & stories
    const realUploadedReels = (reels || [])
      .filter((r: any) => {
        if (!r) return false;
        if (r.privacy === "private" || r.isPrivate) return false;
        const matchesUploader = (r.uploaderId && r.uploaderId === userUniqueId) ||
          (r.creator && (r.creator === userFullName || r.creator === userUsername || r.creator === "You"));
        return matchesUploader;
      })
      .map((r: any) => ({
        id: r.id,
        title: r.caption ? (r.caption.split(" ").slice(0, 4).join(" ") + "...") : (r.title || "My Clip 🎬"),
        views: r.views ?? 0,
        likes: r.likes || 0,
        liked: !!r.liked,
        saved: !!r.saved,
        videoBg: r.videoBg || "bg-gradient-to-tr from-[#ff007f] via-[#12121a] to-[#7b2cbf]",
        videoUrl: r.videoUrl,
        caption: r.caption || r.title || "",
        song: r.song || "Original Audio",
        comments: (r.comments || []).map((c: any) => typeof c === "string" ? c : (c.text || "")),
        duration: r.duration || "0:30",
        location: r.location || "",
        isPrivate: false,
        privacy: "public",
        saves: r.saves || 0,
        creator: r.creator || userFullName || userUsername,
        avatar: r.avatar || user.avatar
      }));

    const realUserStories = (stories || [])
      .filter((s: any) => s && (s.username === userUsername || s.fullName === userFullName || s.userId === userUniqueId))
      .map((s: any) => ({
        id: s.id,
        title: s.caption ? (s.caption.split(" ").slice(0, 4).join(" ") + "...") : "My Story ⚡",
        views: `${(s.reactions?.length || 0) + (s.replies?.length || 0) + 10} Views`,
        likes: s.likes || (s.likedBy?.length || 0),
        liked: s.likedBy?.includes(userUsername) || false,
        saved: false,
        videoBg: s.bgColor || "bg-gradient-to-tr from-[#ff007f] via-purple-900 to-[#7b2cbf]",
        videoUrl: s.videoUrl || s.imageUrl,
        caption: s.caption || s.text || "24h Story",
        song: "Story Audio",
        comments: (s.replies || []).map((r: any) => `${r.username}: ${r.text}`),
        duration: "0:15",
        isPrivate: false,
        privacy: "public",
        saves: 0,
        creator: userFullName || userUsername,
        avatar: user.avatar
      }));

    const combinedUploaded = [...realUploadedReels, ...realUserStories];

    // 2. Collect liked reels & stories
    const realLikedReels = (reels || [])
      .filter((r: any) => r && (r.liked || (r.likedBy && r.likedBy.includes(userUsername))))
      .map((r: any) => ({
        id: r.id,
        title: r.caption ? (r.caption.split(" ").slice(0, 4).join(" ") + "...") : (r.title || "Liked Clip ❤️"),
        views: r.views ?? 0,
        likes: r.likes ?? 0,
        liked: true,
        saved: !!r.saved,
        videoBg: r.videoBg || "bg-gradient-to-tr from-[#ff0055] via-black to-[#7b2cbf]",
        videoUrl: r.videoUrl,
        caption: r.caption || r.title || "",
        song: r.song || "Audio Track",
        comments: (r.comments || []).map((c: any) => typeof c === "string" ? c : (c.text || "")),
        duration: r.duration || "0:30",
        creator: r.creator,
        avatar: r.avatar
      }));

    const realLikedStories = (stories || [])
      .filter((s: any) => s && s.likedBy && s.likedBy.includes(userUsername))
      .map((s: any) => ({
        id: s.id,
        title: s.caption ? (s.caption.split(" ").slice(0, 4).join(" ") + "...") : "Liked Story ❤️",
        views: `${s.likes || 1} Likes`,
        likes: s.likes || 1,
        liked: true,
        saved: false,
        videoBg: s.bgColor || "bg-gradient-to-tr from-pink-500 to-purple-600",
        videoUrl: s.videoUrl || s.imageUrl,
        caption: s.caption || s.text || "Story clip",
        song: "Story Audio",
        comments: [],
        duration: "0:15",
        creator: s.fullName || s.username,
        avatar: s.avatar
      }));

    const combinedLiked = [...realLikedReels, ...realLikedStories];

    // 3. Collect saved reels
    const realSavedReels = (reels || [])
      .filter((r: any) => r && (r.saved || (r.savedBy && r.savedBy.includes(userUsername))))
      .map((r: any) => ({
        id: r.id,
        title: r.caption ? (r.caption.split(" ").slice(0, 4).join(" ") + "...") : (r.title || "Saved Clip 🔖"),
        views: r.views ?? 0,
        likes: r.likes || 0,
        liked: !!r.liked,
        saved: true,
        videoBg: r.videoBg || "bg-gradient-to-tr from-yellow-600 via-black to-purple-800",
        videoUrl: r.videoUrl,
        caption: r.caption || r.title || "",
        song: r.song || "Saved Audio",
        comments: (r.comments || []).map((c: any) => typeof c === "string" ? c : (c.text || "")),
        duration: r.duration || "0:30",
        creator: r.creator,
        avatar: r.avatar
      }));

    // 4. Collect private reels
    const realPrivateReels = (reels || [])
      .filter((r: any) => {
        if (!r) return false;
        if (!(r.privacy === "private" || r.isPrivate)) return false;
        const matchesUploader = (r.uploaderId && r.uploaderId === userUniqueId) ||
          (r.creator && (r.creator === userFullName || r.creator === userUsername || r.creator === "You"));
        return matchesUploader;
      })
      .map((r: any) => ({
        id: r.id,
        title: r.caption ? (r.caption.split(" ").slice(0, 4).join(" ") + "...") : "My Private Clip 🔒",
        views: "Host Private",
        likes: r.likes || 0,
        liked: !!r.liked,
        saved: !!r.saved,
        videoBg: r.videoBg || "bg-gradient-to-tr from-[#11111d] via-[#1a1236] to-[#251025]",
        videoUrl: r.videoUrl,
        caption: r.caption || "",
        song: r.song || "Private Audio",
        comments: [],
        duration: r.duration || "0:30",
        isPrivate: true,
        privacy: "private",
        creator: r.creator || userFullName || userUsername,
        avatar: r.avatar || user.avatar
      }));

    setProfileReels(prev => {
      const prevUploaded = prev.uploaded || [];
      const prevPrivate = prev.private || [];
      const prevLiked = prev.liked || [];
      const prevSaved = prev.saved || [];

      const dedupe = (list: any[]) => {
        const seen = new Set();
        return list.filter(item => {
          if (!item || !item.id) return false;
          if (seen.has(item.id)) return false;
          seen.add(item.id);
          return true;
        });
      };

      const isFakeId = (id: string) => /^[ulsp]\d+$/.test(id);

      const extraUploaded = prevUploaded.filter(p => !combinedUploaded.some(c => c.id === p.id) && !isFakeId(p.id));
      const extraPrivate = prevPrivate.filter(p => !realPrivateReels.some(c => c.id === p.id) && !isFakeId(p.id));
      const extraLiked = prevLiked.filter(p => !combinedLiked.some(c => c.id === p.id) && !isFakeId(p.id));
      const extraSaved = prevSaved.filter(p => !realSavedReels.some(c => c.id === p.id) && !isFakeId(p.id));

      return {
        uploaded: dedupe([...combinedUploaded, ...extraUploaded]),
        liked: dedupe([...combinedLiked, ...extraLiked]),
        saved: dedupe([...realSavedReels, ...extraSaved]),
        private: dedupe([...realPrivateReels, ...extraPrivate])
      };
    });
  }, [reels, stories, user.uniqueId, user.username, user.fullName]);

  // Client Navigation View (within mobile)
  const [clientView, setClientView] = useState<"feed" | "live-room" | "profile" | "wallet" | "family-agency" | "chat" | "reels" | "user-live" | "camera-prep" | "party-room" | "notifications" | "stream">("feed");
  const [viewHistory, setViewHistory] = useState<string[]>(["feed"]);

  useEffect(() => {
    if (clientView === "feed") {
      setViewHistory(["feed"]);
      return;
    }
    setViewHistory((prev) => {
      if (prev[prev.length - 1] === clientView) return prev;
      if (prev.length > 1 && prev[prev.length - 2] === clientView) {
        const copy = [...prev];
        copy.pop();
        return copy;
      }
      return [...prev, clientView];
    });
  }, [clientView]);

  const goBack = () => {
    if (viewHistory.length > 1) {
      const prevView = viewHistory[viewHistory.length - 2];
      setClientView(prevView as any);
    } else {
      setClientView("feed");
    }
  };

  const reelStartTimeRef = useRef<number>(Date.now());
  const prevReelIdRef = useRef<string>("");

  useEffect(() => {
    if (clientView !== "reels") return;
    
    const now = Date.now();
    const elapsed = (now - reelStartTimeRef.current) / 1000;
    
    const prevId = prevReelIdRef.current;
    if (prevId && elapsed > 0.1) {
      setReelInteractions(prev => {
        const existing = prev[prevId] || {
          watchTime: 0,
          completions: 0,
          rewatches: 0,
          skippedQuickly: false,
          likes: 0,
          commentsCount: 0,
          shares: 0,
          saves: 0,
          isFollowed: false
        };
        const newWatchTime = existing.watchTime + elapsed;
        const newCompletions = existing.completions + (elapsed >= 8 ? 1 : 0);
        const newSkippedQuickly = existing.skippedQuickly || (elapsed < 2);
        const newRewatches = existing.rewatches + (elapsed >= 16 ? 1 : 0);
        return {
          ...prev,
          [prevId]: {
            ...existing,
            watchTime: newWatchTime,
            completions: newCompletions,
            skippedQuickly: newSkippedQuickly,
            rewatches: newRewatches
          }
        };
      });
    }

    // Capture the new active reel
    const filtered = reels.filter(r => {
      if (blockedUsers.includes(r.creator)) return false;
      if (reelsTab === "following") return r.isFollowed && r.privacy === "public";
      if (reelsTab === "explore") return r.isExplore && r.privacy === "public";
      return r.privacy === "public";
    });
    
    const sorted = reelsTab === "foryou" ? recommendReels(filtered, reelInteractions) : filtered;
    const currentActiveReel = sorted[currentReelIndex >= sorted.length ? 0 : currentReelIndex];
    
    if (currentActiveReel) {
      prevReelIdRef.current = currentActiveReel.id;
    } else {
      prevReelIdRef.current = "";
    }
    
    reelStartTimeRef.current = now;
  }, [currentReelIndex, reelsTab, clientView]);



