  const handleFullScreenDoubleTap = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const colors = ["#ff007f", "#e01e5a", "#36c5f0", "#ecb22e", "#2eb67d", "#a855f7", "#f43f5e"];
    const color = colors[Math.floor(Math.random() * colors.length)];
    const id = "heart-" + Date.now() + "-" + Math.random().toString(36).substring(2, 6);
    setDoubleTapHearts(prev => [...prev, { id, x, y, color }]);
    setUserLiveLikes(prev => prev + 1);
    setTimeout(() => {
      setDoubleTapHearts(prev => prev.filter(h => h.id !== id));
    }, 1200);
  };
