    if (userLiveCoinsEarned > 0) {
      const newTx: Transaction = {
        id: `TX-EARN-${Date.now().toString().slice(-4)}`,
        type: "recharge", // recharge or earn
        amount: permanentDiamondsEarned,
        currency: "diamonds",
        timestamp: new Date().toISOString().replace("T", " ").slice(0, 16),
        status: "Completed",
        details: `Earned ${permanentDiamondsEarned} Diamonds from Solo Live broadcast`
      };
      setTransactions(prev => [newTx, ...prev]);
    }

    // Completely reset local camera, mic, PK, cohost, and invite states
    setUserLiveCam(false);
    setUserLiveMic(false);
    setUserLivePkActive(false);
    setUserLivePkConnected(false);
