    // Call delete & end endpoints to end stream on backend
    const token = localStorage.getItem("pardais_auth_token");
    const hostId = `h-${user.uniqueId || user.username || "pardais_1001"}`;
    
    // Immediately clear from local stream feed state
    setLiveStreamsList(prev => prev.filter(h => 
      h.id !== hostId && 
      h.id !== `h-${user.username}` &&
      h.hostUsername?.toLowerCase() !== user.username.toLowerCase() && 
      h.name?.toLowerCase() !== user.username.toLowerCase() &&
      h.hostUid !== user.uniqueId &&
      h.hostUid !== user.username
    ));

    console.log("[LIVE END ATTEMPT] Ending active host session on backend:", hostId);
    
    fetch(`/api/v1/hosts/${hostId}/end`, { method: "POST" }).catch(() => {});
