                                            <img
                                              src={activeHost.avatar}
                                              style={{ transform: `rotate(${hostCamRotation}deg)`, transition: "transform 0.3s ease" }}
                                              className="w-full h-full object-cover"
                                              alt="Host thumbnail"
                                            />
