                                    {userLiveMessages.slice(-15).map(msg => (
                                      <div
                                        key={msg.id}
                                        className={`text-[9px] rounded-xl p-1 bg-black/35 text-left`}
                                      >
                                        {msg.isSystem ? (
                                          <p className="leading-normal flex items-center flex-wrap gap-1 bg-transparent text-pink-300">
                                            <span className="text-gray-400 text-[8px]">👤</span>
                                            <span 
                                              onClick={() => {
                                                const targetLvl = msg.userLevel || getHostLevelFromName(msg.username);
                                                setViewerMenuUser({
                                                  username: msg.username,
                                                  userLevel: targetLvl,
                                                  vipLevel: msg.vipLevel || getVipLevelFromUserLevel(targetLvl)
                                                });
                                              }}
                                              className="font-black text-[#66fcf1] hover:text-[#45a29e] hover:underline cursor-pointer transition-colors"
                                            >
                                              {msg.username}
                                            </span>
                                            <span>{msg.message}</span>
                                          </p>
                                        ) : (
                                          <div className="leading-normal bg-transparent">
                                            <span className="flex items-center space-x-1 inline-flex mr-1 align-middle bg-transparent">
                                              {msg.userLevel > 0 && (
                                                <span className="text-[6.5px] bg-purple-600/90 text-white font-black px-1 rounded font-mono">
                                                  {msg.userLevel}
                                                </span>
                                              )}
                                              <span 
                                                onClick={() => {
                                                  const targetLvl = msg.userLevel || getHostLevelFromName(msg.username);
                                                  setViewerMenuUser({
                                                    username: msg.username,
                                                    userLevel: targetLvl,
                                                    vipLevel: msg.vipLevel || getVipLevelFromUserLevel(targetLvl)
                                                  });
                                                }}
                                                className="font-black text-[#66fcf1] hover:text-[#45a29e] hover:underline cursor-pointer transition-colors"
                                              >
                                                {msg.username}
                                              </span>
                                            </span>
                                            <span className="text-gray-200 inline align-middle font-medium">{msg.message}</span>
                                          </div>
                                        )}
                                      </div>
                                    ))}
